import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { migrationsModule } from './migrations';
import { handWrittenModels } from './models';
import { tableDefaults, zodModule } from './zod';

/**
 * Writes every generated file: the row schemas and bundled migrations from the Drizzle schema, then the OpenAPI
 * document, the web client's contract, and the Swift API types from the contract. A file is rewritten only when
 * its content changes, so watchers do not loop. `--check` writes nothing and fails when a file is stale, which CI
 * runs.
 */

const root = join(import.meta.dir, '../..');
const check = process.argv.includes('--check');

const GENERATED = '// Generated by scripts/generate. Do not edit.\n';
const json = (value: unknown) => `${JSON.stringify(value, null, '\t')}\n`;

const read = (path: string) => {
	try {
		return readFileSync(path, 'utf8');
	} catch {
		return null;
	}
};

const stale: string[] = [];
function write(path: string, next: string) {
	const file = join(root, path);
	if (read(file) === next) return;
	stale.push(relative(root, file));
	if (check) return;
	mkdirSync(dirname(file), { recursive: true });
	writeFileSync(file, next);
}

write('shared/db/generated/zod.ts', zodModule());
write('server/src/db/generated/migrations.ts', GENERATED + migrationsModule(join(root, 'server/drizzle')));

// The contract imports the row schemas just written, so it loads only now.
const { minifyContractRouter } = await import('@orpc/contract');
const { contract } = await import('../../shared/api/contract');
const { namedSchemas, openApiDocument } = await import('./openapi');
const { swiftModule } = await import('./swift');
const openApi = json(await openApiDocument());
write('shared/api/generated/openapi.json', openApi);
write('app-web/src/lib/generated/contract.json', json(minifyContractRouter(contract)));
write(
	'app-ios/Sources/Core/Generated/API.swift',
	swiftModule({ components: namedSchemas(), paths: JSON.parse(openApi).paths, tableDefaults: tableDefaults() }),
);

const models = handWrittenModels(root, ['app-ios/Sources']);
if (models.length) {
	console.error(
		`Swift declares models the shared schemas should define. Give the Zod schema an id instead, or list the type in scripts/generate/models.ts with why it stays:\n${models.join('\n')}`,
	);
	process.exit(1);
}

if (check && stale.length) {
	console.error(`Generated files are stale. Run \`bun run generate\` and commit:\n${stale.join('\n')}`);
	process.exit(1);
}
if (!check && stale.length) console.log(`generate: wrote ${stale.join(', ')}`);
